import Foundation

struct Airport: Codable, Hashable, Identifiable, Sendable {
    let icao: String
    let iata: String
    let name: String
    let city: String
    let country: String
    let lat: Double
    let lon: Double
    let tz: String
    let large: Bool

    var id: String { icao }
    var timeZone: TimeZone { TimeZone(identifier: tz) ?? .gmt }
}

/// Airports bundled with the app (generated by worker/scripts/build_airports.py).
final class AirportStore: Sendable {
    static let shared = AirportStore()

    let all: [Airport]
    private let byCode: [String: Airport]

    init(bundle: Bundle = .main) {
        let url = bundle.url(forResource: "airports", withExtension: "json")!
        all = (try? JSONDecoder().decode([Airport].self, from: Data(contentsOf: url))) ?? []
        var index: [String: Airport] = [:]
        for airport in all {
            index[airport.icao] = airport
            if index[airport.iata] == nil { index[airport.iata] = airport }
        }
        byCode = index
    }

    func airport(_ code: String) -> Airport? { byCode[code.uppercased()] }

    /// Exact code matches first, then big airports, then everything else.
    func search(_ query: String, limit: Int = 30) -> [Airport] {
        let q = query.trimmingCharacters(in: .whitespaces).lowercased()
        guard !q.isEmpty else { return all.filter { $0.large && $0.country == "US" }.prefix(limit).map { $0 } }
        func rank(_ a: Airport) -> Int? {
            if a.iata.lowercased() == q || a.icao.lowercased() == q { return 0 }
            if a.iata.lowercased().hasPrefix(q) { return 1 }
            if a.city.lowercased().hasPrefix(q) { return a.large ? 2 : 3 }
            if a.name.lowercased().contains(q) || a.city.lowercased().contains(q) { return a.large ? 4 : 5 }
            return nil
        }
        var ranked: [(airport: Airport, rank: Int)] = []
        for airport in all {
            if let r = rank(airport) { ranked.append((airport, r)) }
        }
        ranked.sort { lhs, rhs in
            lhs.rank == rhs.rank ? lhs.airport.iata < rhs.airport.iata : lhs.rank < rhs.rank
        }
        return ranked.prefix(limit).map(\.airport)
    }
}
